window.kbPageData["views/entry/k-895302ad49793c24"] = {"key":"entry/k-895302ad49793c24","state":{"route":"entry/k-895302ad49793c24"},"node":{"id":"k-895302ad49793c24","mode":"k","title":"退休再就业的劳务关系与工伤保障","type":"制度与规则","domain":"社会治理","reading":"","intro":"","priority":100,"aliases":["材料所述已领取退休金人员再就业的劳动关系与工伤保障限制"],"qs":["国考 2024 行政执法 申论#4"],"current":false,"candidates":true,"sources":[],"basisGroup":"","authority":null,"sourceOnly":false,"reviewSet":"单次条目","independentCount":1,"repeatPositions":0,"directorySummary":"按本题所涉时点适用的司法解释，用人单位招用已依法享受养老保险待遇或者领取退休金的人员，发生用工争议并起诉的，人民法院应按劳务关系处理。符合地方政策条件的超龄从业人员，可由从业单位为其单项参加工伤保险。","review":{"definition":"按本题所涉时点适用的司法解释，用人单位招用已依法享受养老保险待遇或者领取退休金的人员，发生用工争议并起诉的，人民法院应按劳务关系处理。符合地方政策条件的超龄从业人员，可由从业单位为其单项参加工伤保险。","explanation":"材料中的小丁父亲已领取退休金。电力公司认可他的技术和经验，却顾虑工作中发生意外后的赔偿责任，双方最终通过雇主险和意外伤害险安排保障。这是本题归纳“保障不到位”并提出完善保障建议的依据。广东已有针对特定人员的单项参保制度，覆盖符合条件的已享受基本养老保险待遇的超龄从业人员。材料未交代就业地，个案能否走这一渠道取决于当地规则和参保条件。","references":[{"source":"web-7fbc050aabe9a5ce","location":"第三十二条第一款，武汉市人力资源和社会保障局转载","quote":"人民法院应当按劳务关系处理"},{"source":"web-59add0947c3d5731","location":"第二条，适用单位、单项参保和从业人员范围","quote":"包括已享受和未享受机关事业单位或者城镇职工基本养老保险待遇人员"}],"evidence":"已经领取了退休金，无法与用人单位确立劳动关系，自然也不能缴纳工伤保险","disposition":"独立词条","basis":"据原题与所列资料编释。"}},"questions":{"国考 2024 行政执法 申论#4":{"paper":"国考 2024 行政执法 申论","n":4,"mod":"申论","src":["b9a9a500aad1608fddd0.pdf",4],"asrc":["b899d5c3aecda01e69ec.pdf",3],"card":"44c39e0143d5392ac682454f","links":[{"id":"k-895302ad49793c24","role":"直接考查","why":"材料把已领取退休金作为个案条件，并将工伤保障缺口与用人单位的赔偿顾虑联系起来。"}]}},"terms":{},"references":{"web-7fbc050aabe9a5ce":{"name":"最高人民法院《关于审理劳动争议案件适用法律问题的解释（一）》","url":"https://rsj.wuhan.gov.cn/zwgk_17/zc/qtzdgkwj/zcfg/202204/t20220427_1963228.html"},"web-59add0947c3d5731":{"name":"广东省《关于单位从业的超过法定退休年龄劳动者等特定人员参加工伤保险的办法（试行）》","url":"https://guangdong.chinatax.gov.cn/gdsw/zssw_gkwj/2021-01/25/content_63032a3a676b4b70b6dfb9e835a23ba9.shtml"}},"topics":[],"units":{"k-895302ad49793c24":[["国考 2024 行政执法 申论#4"]]}};
